// Access layer for content generated by scripts/build-content.mjs.
import site from '../generated/site.json'

export const pages = site.pages
export const filters = site.filters
export const totals = site.totals

const byId = new Map(pages.map((p) => [p.id, p]))
export const pageById = (id) => byId.get(id)

// Top-level navigation sections in category-tree order (Home and Legal Notice excluded).
export const sections = pages.filter((p) => !p.parent && p.url !== '/' && p.type !== 'legal')

// Breadcrumb trail from the top-level section down to the page, excluding Home.
export function trail(id) {
  const out = []
  for (let p = byId.get(id); p; p = p.parent && byId.get(p.parent)) out.unshift(p)
  return out
}

const cache = new Map()
const getJson = (url) => {
  if (!cache.has(url)) {
    cache.set(
      url,
      fetch(url).then((r) => {
        if (!r.ok) throw new Error(`${r.status} ${url}`)
        return r.json()
      }),
    )
  }
  return cache.get(url)
}

// Editorial copy: { id, sections: [{ h, blocks: [{ p } | { ul: [] }] }] }
export const loadPageContent = (id) => getJson(`/data/pages/${id}.json`)

// Product rows for one primary category shard, decoded to objects.
export async function loadShard(id) {
  const { fields, rows } = await getJson(`/data/products/${id}.json`)
  return rows.map((r) => Object.fromEntries(fields.map((f, i) => [f, r[i]])))
}
